// src/plugins/auth.ts
var authMacro = new Elysia({ name: "auth-macro" }).macro({
  auth: {
    async resolve({ status: status2, request: { headers } }) {
      const session = await auth.api.getSession({ headers });
      if (!session) {
        return status2(401, { error: "Unauthorized" });
      }
      return {
        user: session.user,
        session: session.session
      };
    }
  },
  admin: {
    async resolve({ status: status2, request: { headers } }) {
      const session = await auth.api.getSession({ headers });
      if (!session) {
        return status2(401, { error: "Unauthorized" });
      }
      const role = session.user.role;
      if (role !== "admin") {
        return status2(403, { error: "Forbidden" });
      }
      return {
        user: session.user,
        session: session.session
      };
    }
  }
});

