function isS3Configured() {
  return getClient() !== null;
}
async function generatePresignedPutUrl(key, contentType) {
  const client2 = getClient();
  const bucket = process.env.AWS_S3_BUCKET;
  const region = process.env.AWS_REGION;
  if (!client2 || !bucket || !region)
    return null;
  const command = new PutObjectCommand({
    Bucket: bucket,
    Key: key,
    ContentType: contentType
  });
  const uploadUrl = await getSignedUrl(client2, command, { expiresIn: 3600 });
  const publicUrl = `https://${bucket}.s3.${region}.amazonaws.com/${key}`;
  return { uploadUrl, publicUrl };
}
async function deleteS3Object(key) {
  const client2 = getClient();
  const bucket = process.env.AWS_S3_BUCKET;
  if (!client2 || !bucket)
    return;
  await client2.send(new DeleteObjectCommand({
    Bucket: bucket,
    Key: key
  }));
}
function parseS3KeyFromPublicUrl(url2) {
  try {
    const u3 = new URL(url2);
    const host = u3.hostname;
    const bucket = process.env.AWS_S3_BUCKET;
    const region = process.env.AWS_REGION;
    if (!bucket || !region)
      return null;
    if (host === `${bucket}.s3.${region}.amazonaws.com`) {
      return u3.pathname.replace(/^\//, "");
    }
    if (host === `${bucket}.s3.amazonaws.com`) {
      return u3.pathname.replace(/^\//, "");
    }
    return null;
  } catch {
    return null;
  }
}

// src/routes/upload.ts
var ALLOWED_CONTENT_TYPES = new Set([
  "image/png",
  "image/jpeg",
  "image/gif",
  "image/webp",
  "image/svg+xml",
  "application/pdf"
]);
var MAX_UPLOAD_BYTES = {
  "application/pdf": 10 * 1024 * 1024
};
var DEFAULT_MAX_UPLOAD_BYTES = 5 * 1024 * 1024;
var uploadRoutes = new Elysia().use(authMacro).post("/api/upload/presigned-url", async ({ user, body, set: set2 }) => {
  if (!isS3Configured()) {
    set2.status = 503;
    return { error: "File uploads are not configured" };
  }
  if (!ALLOWED_CONTENT_TYPES.has(body.contentType)) {
    set2.status = 400;
    return { error: "Unsupported file type" };
  }
  const maxBytes = MAX_UPLOAD_BYTES[body.contentType] ?? DEFAULT_MAX_UPLOAD_BYTES;
  if (body.contentLength !== undefined && body.contentLength > maxBytes) {
    set2.status = 400;
    return { error: `File is too large (max ${Math.round(maxBytes / (1024 * 1024))} MB)` };
  }
  const u3 = user;
  const safeName = body.filename.replace(/[^a-zA-Z0-9._-]/g, "_");
  const key = `uploads/${u3.id}/${Date.now()}-${safeName}`;
  const result = await generatePresignedPutUrl(key, body.contentType);
  if (!result) {
    set2.status = 503;
    return { error: "Could not create upload URL" };
  }
  return {
    uploadUrl: result.uploadUrl,
    key,
    publicUrl: result.publicUrl
  };
}, {
  auth: true,
  body: t.Object({
    filename: t.String({ minLength: 1 }),
    contentType: t.String({ minLength: 1 }),
    contentLength: t.Optional(t.Number())
  })
}).delete("/api/upload", async ({ user, body, set: set2 }) => {
  if (!isS3Configured()) {
    set2.status = 503;
    return { error: "File uploads are not configured" };
  }
  const u3 = user;
  const key = parseS3KeyFromPublicUrl(body.publicUrl);
  if (!key || !key.startsWith(`uploads/${u3.id}/`)) {
    set2.status = 400;
    return { error: "Invalid file URL" };
  }
  await deleteS3Object(key);
  set2.status = 204;
  return null;
}, { auth: true, body: t.Object({ publicUrl: t.String() }) });

// src/lib/rate-limit.ts
var buckets = new Map;
setInterval(() => {
  const now2 = Date.now();
  for (const [key, bucket] of buckets) {
    if (bucket.resetAt <= now2)
      buckets.delete(key);
  }
}, 60000).unref?.();
function isRateLimited(key, limit, windowMs) {
  const now2 = Date.now();
  const bucket = buckets.get(key);
  if (!bucket || bucket.resetAt <= now2) {
    buckets.set(key, { count: 1, resetAt: now2 + windowMs });
    return false;
  }
  if (bucket.count >= limit) {
    return true;
  }
  bucket.count += 1;
  return false;
}

// src/lib/request-ip.ts
function getClientIp(request2, server) {
  const forwarded = request2.headers.get("x-forwarded-for");
  if (forwarded) {
    const first = forwarded.split(",")[0]?.trim();
    if (first)
      return first;
  }
  const real = request2.headers.get("x-real-ip");
  if (real)
    return real;
  const socket = server?.requestIP(request2);
  return socket?.address ?? "unknown";
}

// src/routes/portfolio.ts
var CONTACT_RATE_LIMIT = 5;
var CONTACT_RATE_WINDOW_MS = 10 * 60 * 1000;
function publicProfile(profile) {
  return {
    id: profile.id,
    username: profile.username,
    displayName: profile.displayName,
    title: profile.title,
    bio: profile.bio,
    photoUrl: profile.photoUrl,
    resumeUrl: profile.resumeUrl,
    githubUrl: profile.githubUrl,
    linkedinUrl: profile.linkedinUrl,
    twitterUrl: profile.twitterUrl,
    websiteUrl: profile.websiteUrl,
    emailPublic: profile.emailPublic,
    activeTemplate: profile.activeTemplate
  };
}
function publicProject(project) {
  return {
    id: project.id,
    name: project.name,
    image: project.image,
    description: project.description,
    tags: project.tags,
    demoUrl: project.demoUrl,
    sourceUrl: project.sourceUrl,
    order: project.order
  };
}
function publicCertificate(certificate) {
  return {
    id: certificate.id,
    name: certificate.name,
    image: certificate.image,
    description: certificate.description,
    url: certificate.url,
    order: certificate.order
  };
}
function publicEvent(event) {
  return {
    id: event.id,
    name: event.name,
    image: event.image,
    description: event.description,
    url: event.url,
    order: event.order
  };
}
function publicGithubConfig(config4) {
  if (!config4)
    return null;
  return {
    githubUsername: config4.githubUsername,
    selectedRepos: config4.selectedRepos
  };
}
function publicSeoMeta(seo) {
  if (!seo)
    return null;
  return {
    title: seo.title,
    description: seo.description,
    ogImage: seo.ogImage,
    keywords: seo.keywords
  };
}
var portfolioPublicRoutes = new Elysia().get("/api/portfolio/sitemap", async () => {
  const profiles = await prisma.profile.findMany({
    where: { published: true },
    select: {
      username: true,
      activeTemplate: true,
      updatedAt: true
    }
  });
  return {
    profiles: profiles.map((p3) => ({
      username: p3.username,
      activeTemplate: p3.activeTemplate,
      updatedAt: p3.updatedAt.toISOString()
    }))
  };
}).get("/api/portfolio/:username", async ({ params, set: set2 }) => {
  const username = params.username.trim().toLowerCase();
  const profile = await prisma.profile.findUnique({
    where: { username }
  });
  if (!profile || !profile.published) {
    set2.status = 404;
    return { error: "Portfolio not found" };
  }
  const userId = profile.userId;
  const [projects, certificates, events, githubConfig, seoMeta] = await Promise.all([
    prisma.project.findMany({
      where: { userId },
      orderBy: [{ order: "asc" }, { createdAt: "asc" }]
    }),
    prisma.certificate.findMany({
      where: { userId },
      orderBy: [{ order: "asc" }, { createdAt: "asc" }]
    }),
    prisma.event.findMany({
      where: { userId },
      orderBy: [{ order: "asc" }, { createdAt: "asc" }]
    }),
    prisma.githubConfig.findUnique({ where: { userId } }),
    prisma.sEOMeta.findUnique({ where: { userId } })
  ]);
  return {
    profile: publicProfile(profile),
    projects: projects.map(publicProject),
    certificates: certificates.map(publicCertificate),
    events: events.map(publicEvent),
    githubConfig: publicGithubConfig(githubConfig),
    seoMeta: publicSeoMeta(seoMeta)
  };
}, { params: t.Object({ username: t.String() }) }).get("/api/portfolio/:username/github", async ({ params, set: set2 }) => {
  const username = params.username.trim().toLowerCase();
  const profile = await prisma.profile.findUnique({
    where: { username },
    select: { userId: true, published: true }
  });
  if (!profile || !profile.published) {
    set2.status = 404;
    return { error: "Portfolio not found" };
  }
  const config4 = await prisma.githubConfig.findUnique({
    where: { userId: profile.userId }
  });
  if (!config4 || config4.selectedRepos.length === 0) {
    return { githubUsername: config4?.githubUsername ?? null, repos: [] };
  }
  try {
    const allRepos = await fetchPublicRepos(config4.githubUsername);
    const byName = new Map(allRepos.map((r2) => [r2.name, r2]));
    const repos = config4.selectedRepos.map((name2) => byName.get(name2)).filter((r2) => Boolean(r2));
    return { githubUsername: config4.githubUsername, repos };
  } catch {
    return { githubUsername: config4.githubUsername, repos: [] };
  }
}, { params: t.Object({ username: t.String() }) }).post("/api/portfolio/:username/contact", async ({ params, body, set: set2, request: request2, server }) => {
  if (body.company) {
    set2.status = 201;
    return { ok: true };
  }
  const ip = getClientIp(request2, server);
  if (isRateLimited(`contact:${ip}`, CONTACT_RATE_LIMIT, CONTACT_RATE_WINDOW_MS)) {
    set2.status = 429;
    return { error: "Too many messages sent. Please try again later." };
  }
  if (!isValidEmail(body.email.trim())) {
    set2.status = 400;
    return { error: "Invalid email address" };
  }
  const username = params.username.trim().toLowerCase();
  const profile = await prisma.profile.findUnique({
    where: { username },
    select: { userId: true, published: true }
  });
  if (!profile || !profile.published) {
    set2.status = 404;
    return { error: "Portfolio not found" };
  }
  await prisma.contactMessage.create({
    data: {
      userId: profile.userId,
      name: body.name.trim(),
      email: body.email.trim(),
      subject: body.subject.trim(),
      message: body.message.trim()
    }
  });
  set2.status = 201;
  return { ok: true };
}, {
  params: t.Object({ username: t.String() }),
  body: t.Object({
    name: t.String({ minLength: 1, maxLength: 100 }),
    email: t.String({ minLength: 3, maxLength: 254 }),
    subject: t.String({ minLength: 1, maxLength: 200 }),
    message: t.String({ minLength: 1, maxLength: 5000 }),
    company: t.Optional(t.String({ maxLength: 200 }))
  })
});

// src/routes/admin.ts
var adminRoutes = new Elysia().use(authMacro).get("/api/admin/overview", async () => {
  const [userCount, profileCount, messageCount] = await Promise.all([
    prisma.user.count(),
    prisma.profile.count(),
    prisma.contactMessage.count()
  ]);
  return { userCount, profileCount, messageCount };
}, { admin: true }).get("/api/admin/users", async ({ query }) => {
  const page = Math.max(1, Number(query.page ?? 1));
  const limit = Math.min(50, Math.max(1, Number(query.limit ?? 20)));
  const search = query.search?.trim();
  const where = search ? {
    OR: [
      { email: { contains: search, mode: "insensitive" } },
      { name: { contains: search, mode: "insensitive" } },
      {
        profile: {
          username: {
            contains: search,
            mode: "insensitive"
          }
        }
      }
    ]
  } : {};
  const [users, total] = await Promise.all([
    prisma.user.findMany({
      where,
      orderBy: { createdAt: "desc" },
      skip: (page - 1) * limit,
      take: limit,
      select: {
        id: true,
        name: true,
        email: true,
        role: true,
        createdAt: true,
        profile: { select: { username: true } }
      }
    }),
    prisma.user.count({ where })
  ]);
  return { users, total, page, limit };
}, {
  admin: true,
  query: t.Object({
    page: t.Optional(t.String()),
    limit: t.Optional(t.String()),
    search: t.Optional(t.String())
  })
}).get("/api/admin/users/:id", async ({ params, set: set2 }) => {
  const user = await prisma.user.findUnique({
    where: { id: params.id },
    include: {
      profile: true,
      _count: {
        select: {
          projects: true,
          certificates: true,
          messages: true
        }
      }
    }
  });
  if (!user) {
    set2.status = 404;
    return { error: "Not found" };
  }
  return { user };
}, { admin: true, params: t.Object({ id: t.String() }) }).patch("/api/admin/users/:id", async ({ params, body, user, set: set2 }) => {
  const admin = user;
  const role = body.role;
  if (role !== "admin" && role !== "user") {
    set2.status = 400;
    return { error: "Invalid role" };
  }
  if (params.id === admin.id && role === "user") {
    set2.status = 400;
    return { error: "Cannot demote yourself" };
  }
  const existing = await prisma.user.findUnique({
    where: { id: params.id }
  });
  if (!existing) {
    set2.status = 404;
    return { error: "Not found" };
  }
  const updated = await prisma.user.update({
    where: { id: params.id },
    data: { role },
    select: {
      id: true,
      name: true,
      email: true,
      role: true,
      createdAt: true,
      profile: { select: { username: true } }
    }
  });
  return { user: updated };
}, {
  admin: true,
  params: t.Object({ id: t.String() }),
  body: t.Object({ role: t.String() })
}).delete("/api/admin/users/:id", async ({ params, user, set: set2 }) => {
  const admin = user;
  if (params.id === admin.id) {
    set2.status = 400;
    return { error: "Cannot delete yourself" };
  }
  const existing = await prisma.user.findUnique({
    where: { id: params.id }
  });
  if (!existing) {
    set2.status = 404;
    return { error: "Not found" };
  }
  await prisma.user.delete({ where: { id: params.id } });
  set2.status = 204;
  return null;
}, { admin: true, params: t.Object({ id: t.String() }) });

// src/index.ts
var origins = [
  process.env.NEXT_PUBLIC_APP_URL ?? "http://localhost:3000",
  process.env.NEXT_PUBLIC_DASHBOARD_URL ?? "http://localhost:3003",
  process.env.NEXT_PUBLIC_PORTFOLIO_URL ?? "http://localhost:3002",
  process.env.NEXT_PUBLIC_WEBSITE_URL ?? "http://localhost:3004"
];
var app = new Elysia().use(cors({
  origin: origins,
  methods: ["GET", "POST", "PUT", "PATCH", "DELETE", "OPTIONS"],
  credentials: true,
  allowedHeaders: ["Content-Type", "Authorization"]
})).onError(({ code, error: error50, set: set2 }) => {
  if (code === "VALIDATION") {
    set2.status = 400;
    const first = error50.all[0];
    const message2 = (first?.summary ? String(first.summary) : undefined) ?? (typeof first?.message === "string" ? first.message : undefined) ?? "Invalid request";
    return { error: message2 };
  }
  if (code === "NOT_FOUND") {
    set2.status = 404;
    return { error: "Not found" };
  }
  console.error(error50);
  if (!set2.status || set2.status === 200) {
    set2.status = 500;
  }
  return { error: "Internal server error" };
}).mount(auth.handler).use(portfolioPublicRoutes).use(profileRoutes).use(projectRoutes).use(certificateRoutes).use(eventRoutes).use(githubRoutes).use(messageRoutes).use(seoRoutes).use(uploadRoutes).use(adminRoutes).get("/health", () => ({ ok: true })).listen(3001);
console.log(`Backend listening on http://localhost:${app.server?.port}`);
